def evaluate_gate(candidate_metrics: dict, champion_metrics: dict) -> tuple[bool, list[str]]:
    failures = []

    # Absolute threshold gate
    if candidate_metrics["f1"] < 0.82:
        failures.append(f"F1 {candidate_metrics['f1']:.3f} below minimum 0.82")

    # Regression guard vs. champion
    auc_delta = candidate_metrics["auc"] - champion_metrics["auc"]
    if auc_delta < -0.005:
        failures.append(f"AUC regressed by {-auc_delta:.4f} vs champion")

    # Latency gate
    if candidate_metrics["p99_latency_ms"] > 50:
        failures.append(f"p99 latency {candidate_metrics['p99_latency_ms']}ms exceeds 50ms SLA")

    # Fairness gate
    if candidate_metrics["demographic_parity_gap"] > 0.05:
        failures.append(f"Demographic parity gap {candidate_metrics['demographic_parity_gap']:.3f} exceeds 0.05")

    return len(failures) == 0, failures

from metaflow import FlowSpec, step, batch, resources, Parameter

class TrainingFlow(FlowSpec):
    learning_rate = Parameter('lr', default=0.001)

    @step
    def start(self):
        self.dataset_version = "v2.3.1"
        self.next(self.preprocess)

    @batch(cpu=4, memory=16000)
    @step
    def preprocess(self):
        # Runs on AWS Batch — same Python code as local execution
        import pandas as pd
        self.features = load_and_transform(self.dataset_version)
        self.next(self.train)

    @resources(gpu=1, memory=32000)
    @batch
    @step
    def train(self):
        model = build_model(lr=self.learning_rate)
        model.fit(self.features)
        self.model = model           # automatically versioned
        self.metrics = evaluate(model)
        self.next(self.end)

    @step
    def end(self):
        print(f"Training complete. AUC: {self.metrics['auc']:.4f}")

if __name__ == '__main__':
    TrainingFlow()
